const HERE = dirname(fileURLToPath(import.meta.url));
const WEB_ROOT = join(HERE, '..');
const VECTORS = join(WEB_ROOT, 'src', 'model', 'agent', 'native', 'vectors');
const ORACLE_RUN = join(WEB_ROOT, 'oracle', 'minitest_voff', 'run');

// ---------------------------------------------------------------------------
// float bit helpers — comparisons are on bits, never on `toBe`-ed numbers
// ---------------------------------------------------------------------------

const f32Buffer = new Float32Array(1);
const f32View = new DataView(f32Buffer.buffer);

function bitsOf(value: number): number {
  f32Buffer[0] = value;
  return f32View.getUint32(0, true);
}

function fromBits(bits: number): number {
  f32View.setUint32(0, bits, true);
  return f32Buffer[0]!;
}

interface CollisionVector {
  readonly kind: string;
  readonly cases: readonly { readonly in: readonly number[]; readonly out: readonly number[] }[];
}

interface EnergyVector {
  readonly kind: string;
  readonly cases: readonly {
    readonly n: number;
    readonly op: number;
    readonly a: readonly number[];
    readonly b: readonly number[];
    readonly m: readonly number[];
    readonly p: readonly number[];
    readonly out: readonly number[];
    readonly ov: readonly number[];
    readonly extra: number;
    readonly extra2: number;
    readonly flag: number;
  }[];
}

interface ConfigVector {
  readonly kind: string;
  readonly worldfile: string;
  readonly keys: Record<string, string>;
  readonly config: Record<string, number>;
  readonly longs: Record<string, number>;
  readonly bools: Record<string, boolean>;
  readonly enums: Record<string, number>;
}

interface LifespanVector {
  readonly kind: string;
  readonly birth: readonly string[];
  readonly death: readonly string[];
}

function loadVector<T>(name: string): T {
  return JSON.parse(readFileSync(join(VECTORS, name), 'utf8')) as T;
}

// ---------------------------------------------------------------------------
// 1. differential: agent::GetCollisionFixedCoordinates
// ---------------------------------------------------------------------------

describe('agent::GetCollisionFixedCoordinates — native differential vectors', () => {
  const vector = loadVector<CollisionVector>('collision.json');
  const deps = makeDeps();

  it('has a native-generated case set', () => {
    expect(vector.kind).toBe('agent.GetCollisionFixedCoordinates');
    expect(vector.cases.length).toBeGreaterThan(3000);
  });

  it('reproduces every native case bit-for-bit (3022/3022)', () => {
    // MEASURED 2026-09-28 against the native vectors: bit-exact on all 3022 cases — the 16
    // crafted branch/early-out cases, the 6 crafted *contraction* cases (t_4392393c) and the
    // 3000 random ones. The native trees are compiled with clang `-O2` and its default
    // `-ffp-contract=on`, so every `a*b + c` in the native source is one `fmadd`/`fmsub`
    // rounding rather than the multiply-then-add of the source text; `agent.ts` transcribes
    // the contraction the disassembled `agent::GetCollisionFixedCoordinates` (0x27504)
    // actually performs (`f32Fma` in `numeric.ts`, PORT-NOTE `L8/contraction`, PARITY.md ->
    // the float-contraction rule). Rounding per operation instead leaves 65 of the random
    // cases last-bit inexact (worst |delta| 5.455017e-4) and fails all 6 crafted contraction
    // cases — the tolerance this test used to carry. It is gone: any drift in any case, in
    // either coordinate, now fails here.
    const NATIVE_CASES = 3022;

    let exact = 0;
    const failures: string[] = [];
    for (const [index, testCase] of vector.cases.entries()) {
      const args = testCase.in.map(fromBits);
      const agent = new Agent(deps);
      const result = agent.getCollisionFixedCoordinates(
        args[0]!,
        args[1]!,
        args[2]!,
        args[3]!,
        args[4]!,
        args[5]!,
        args[6]!,
        args[7]!,
      );
      const wantX = fromBits(testCase.out[0]!);
      const wantZ = fromBits(testCase.out[1]!);
      if (bitsOf(result.xf) === testCase.out[0] && bitsOf(result.zf) === testCase.out[1]) {
        exact++;
        continue;
      }
      failures.push(
        `case ${index}: in=[${args.join(',')}] got (${result.xf}, ${result.zf}) ` +
          `want (${wantX}, ${wantZ})`,
      );
    }

    expect(vector.cases.length).toBe(NATIVE_CASES);
    expect(failures.slice(0, 5)).toEqual([]);
    expect(exact, `${exact}/${vector.cases.length} cases bit-exact`).toBe(NATIVE_CASES);
  });
});

// ---------------------------------------------------------------------------
// 2. differential: environment/Energy arithmetic
// ---------------------------------------------------------------------------

describe('Energy arithmetic — native differential vectors', () => {
  const vector = loadVector<EnergyVector>('energy.json');

  it('has a native-generated case set', () => {
    expect(vector.kind).toBe('environment.Energy');
    expect(vector.cases.length).toBeGreaterThan(500);
  });

  it('reproduces every op bit-for-bit', () => {
    const failures: string[] = [];
    for (const [index, testCase] of vector.cases.entries()) {
      const { n, op } = testCase;
      globals.numEnergyTypes = n;

      const a = Energy.fromNumbers(testCase.a.map(fromBits));
      const b = Energy.fromNumbers(testCase.b.map(fromBits));
      const m = EnergyMultiplier.fromNumbers(testCase.m.map(fromBits));
      const polarity = EnergyPolarity.fromNumbers(testCase.p);

      const out = new Energy(0);
      const ov = new Energy(0);
      let extra = 0;
      let extra2 = 0;
      let flag = 0;

      switch (op) {
        case 0: {
          const r = energyAdd(a, b);
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        case 1: {
          const r = energySub(a, b);
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        case 2: {
          const r = a.mulScalar(fromBits(testCase.b[0]!));
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        case 3: {
          const r = a.mulPolarity(polarity);
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        case 4: {
          const r = a.mulMultiplier(m);
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        case 5: {
          // native: min is b[0] broadcast, max is the M array read as an Energy
          const e = a.clone();
          const overflow = e.constrainOverflow(
            new Energy(fromBits(testCase.b[0]!)),
            Energy.fromNumbers(testCase.m.map(fromBits)),
          );
          for (let i = 0; i < n; i++) {
            out.set(i, e.get(i));
            ov.set(i, overflow.get(i));
          }
          break;
        }
        case 6: {
          extra = a.sum();
          extra2 = a.mean();
          flag = (a.isZero() ? 1 : 0) | (a.isDepleted(b) ? 2 : 0);
          break;
        }
        case 7: {
          const r = Energy.createDepletionThreshold(a, polarity);
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        case 8: {
          const r = Energy.fromPolarity(a, b, polarity);
          for (let i = 0; i < n; i++) out.set(i, r.get(i));
          break;
        }
        default: {
          const e = a.clone();
          e.addAssign(b);
          for (let i = 0; i < n; i++) out.set(i, e.get(i));
          break;
        }
      }

      const check = (name: string, actual: number, expected: number): void => {
        // NaN is an expected result (createDepletionThreshold's UNDEFINED polarity);
        // compare its bit pattern like any other value.
        if (bitsOf(actual) !== expected) {
          failures.push(`case ${index} (op ${op}, n ${n}) ${name}: got ${bitsOf(actual)} want ${expected}`);
        }
      };

      for (let i = 0; i < n; i++) {
        check(`out[${i}]`, out.get(i), testCase.out[i]!);
        check(`ov[${i}]`, ov.get(i), testCase.ov[i]!);
      }
      check('extra', extra, testCase.extra);
      check('extra2', extra2, testCase.extra2);
      if (flag !== testCase.flag) failures.push(`case ${index} flag: got ${flag} want ${testCase.flag}`);
    }

    expect(failures.slice(0, 5)).toEqual([]);
    expect(failures.length).toBe(0);
  });
});

// ---------------------------------------------------------------------------
// 3. differential: agent::processWorldfile
// ---------------------------------------------------------------------------

describe('agent::processWorldfile — native config for the recorded worldfile', () => {
  const vector = loadVector<ConfigVector>('config.minitest_voff.json');

  beforeEach(() => {
    resetAgentConfig();
    resetAgentStatics();
  });

  it('reads every key through the same coercion the native build used', () => {
    expect(vector.kind).toBe('agent.processWorldfile');
    expect(vector.worldfile).toContain('minitest.wf');

    // The probe dumped the *evaluated* string of each key from the document the native run
    // configured from, so this replays native's own text, not a re-typed copy of it.
    processWorldfile(documentFromJs(vector.keys));

    const mismatches: string[] = [];
    for (const [name, bits] of Object.entries(vector.config)) {
      const actual = (agentConfig as unknown as Record<string, number>)[name] ?? Number.NaN;
      if (bitsOf(actual) !== bits) {
        mismatches.push(`config.${name}: got ${bitsOf(actual)} want ${bits}`);
      }
    }
    for (const [name, value] of Object.entries(vector.longs)) {
      const actual = (agentConfig as unknown as Record<string, number>)[name] ?? Number.NaN;
      if (actual !== value) mismatches.push(`config.${name}: got ${actual} want ${value}`);
    }
    for (const [name, value] of Object.entries(vector.bools)) {
      const actual = (agentConfig as unknown as Record<string, boolean>)[name];
      if (actual !== value) mismatches.push(`config.${name}: got ${actual} want ${value}`);
    }
    for (const [name, value] of Object.entries(vector.enums)) {
      const actual = (agentConfig as unknown as Record<string, number>)[name];
      if (actual !== value) mismatches.push(`config.${name}: got ${actual} want ${value}`);
    }

    expect(mismatches).toEqual([]);
  });

  it('derives hasLightBehavior from the channel selections, as native does', () => {
    processWorldfile(documentFromJs(vector.keys));
    expect(agentConfig.bodyGreenChannel).toBe(BodyGreenChannel.BGC_ID);
    expect(agentConfig.noseColor).toBe(0); // NC_LIGHT
    expect(agentConfig.hasLightBehavior).toBe(true);
    expect(agentConfig.bodyRedChannel).toBe(BodyRedChannel.BRC_FIGHT);
    expect(agentConfig.bodyBlueChannel).toBe(BodyBlueChannel.BBC_MATE);
    expect(agentConfig.dieAtMaxAge).toBe(true);
  });

  it('reads a constant body channel as a float when it is not a keyword', () => {
    const keys = { ...vector.keys, BodyRedChannel: '0.25', NoseColor: '0.75' };
    processWorldfile(documentFromJs(keys));
    expect(agentConfig.bodyRedChannel).toBe(BRC.BRC_CONST);
    expect(agentConfig.bodyRedChannelConstValue).toBe(f32(0.25));
    expect(agentConfig.noseColor).toBe(2); // NC_CONST
    expect(agentConfig.noseColorConstValue).toBe(f32(0.75));
    // bodyGreenChannel is still 'I' (BGC_ID) and the nose is now a constant, so neither
    // light-behaviour trigger fires.
    expect(agentConfig.bodyGreenChannel).toBe(BodyGreenChannel.BGC_ID);
    expect(agentConfig.hasLightBehavior).toBe(false);
  });

  it('rejects an unknown YawEncoding instead of guessing (native asserts)', () => {
    const keys = { ...vector.keys, YawEncoding: 'Sideways' };
    expect(() => processWorldfile(documentFromJs(keys))).toThrow(/YawEncoding/);
  });
});

