// ---------------------------------------------------------------------------
// 5. oracle-anchored invariants (skipped without the goldens)
// ---------------------------------------------------------------------------

const hasGoldens = existsSync(join(ORACLE_RUN, 'lifespans.txt'));
const golden = hasGoldens ? describe : describe.skip;

golden('minitest_voff goldens — per-agent logs bracket the LifeSpan exactly', () => {
  const lifespans = readLifespans();
  const agents = [...lifespans.keys()].sort((a, b) => a - b);

  it('records 87 agents with a SIMINIT or NATURAL birth', () => {
    expect(agents.length).toBe(87);
    for (const [, entry] of lifespans) {
      expect(['SIMINIT', 'NATURAL']).toContain(entry.birthReason);
    }
  });

  it('starts each energy series at the birth step (the step after, for SIMINIT at step 0)', () => {
    for (const number of agents) {
      const entry = lifespans.get(number)!;
      const steps = logSteps(join(ORACLE_RUN, 'energy', 'agents', `agent_${number}.txt`));
      expect(steps.length).toBeGreaterThan(0);
      expect(steps[0]).toBe(entry.birthStep === 0 ? 1 : entry.birthStep);
      expect(steps[steps.length - 1]).toBe(entry.deathStep);
      expect(isContiguous(steps)).toBe(true);
      expect(steps.length).toBe(entry.deathStep - steps[0]! + 1);    }
  });

  it('starts each position series on the step after birth and ends it at death', () => {
    for (const number of agents) {
      const entry = lifespans.get(number)!;
      const steps = logSteps(join(ORACLE_RUN, 'motion', 'position', 'agents', `position_${number}.txt`));
      expect(steps.length).toBeGreaterThan(0);
      expect(steps[0]).toBe(entry.birthStep + 1);
      expect(steps[steps.length - 1]).toBe(entry.deathStep);
      expect(isContiguous(steps)).toBe(true);
    }
  });

  it('ends every agent at or before the final step, with SIMEND only for survivors', () => {
    const finalStep = Math.max(...[...lifespans.values()].map((entry) => entry.deathStep));
    for (const [, entry] of lifespans) {
      expect(entry.deathStep).toBeLessThanOrEqual(finalStep);
      if (entry.deathReason === 'SIMEND') expect(entry.deathStep).toBe(finalStep);
    }
  });
});

// ---------------------------------------------------------------------------
// 6. behaviour pins on the ported step, over the real worldfile's config
// ---------------------------------------------------------------------------

describe('Agent — the ported step (UpdateBody) and lifecycle', () => {
  const configVector = loadVector<ConfigVector>('config.minitest_voff.json');

  beforeEach(() => {
    resetGlobals();
    resetAgentConfig();
    resetAgentStatics();
    // Use the *recorded* worldfile's agent configuration (dumped by the native probe), so
    // these pins exercise the values the goldens were produced with.
    processWorldfile(documentFromJs(configVector.keys));
    globals.worldsize = 100;
    globals.numEnergyTypes = 1; // the recorded world's NumEnergyTypes
  });

  it('moves and drains energy by the native formula', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();

    const nerves = deps.testNerves!;
    nerves.set('Eat', 0.25);
    nerves.set('Mate', 0);
    nerves.set('Fight', 0);
    nerves.set('Speed', 0.5);
    nerves.set('Yaw', 0.75); // YE_OPPOSE: yaw - yawOppose
    nerves.set('YawOppose', 0.25);
    nerves.set('Focus', 0);

    const before = agent.energy().clone();
    const maxEnergy = agent.maxEnergy().get(0);
    const genes = deps.testGenes!;
    const ageBefore = agent.age();
    const positionBefore: [number, number, number] = [agent.x(), agent.y(), agent.z()];

    const energyUsed = agent.updateBody(1.0, agentConfig.speed2DPosition, 0, null);

    // --- the native expression, written out independently -------------------
    const dposRaw = f32(f32(0.5 * genes.maxSpeed) * agentConfig.speed2DPosition);
    const dpos = dposRaw > agentConfig.maxVelocity ? agentConfig.maxVelocity : dposRaw;
    const dyaw = f32(0.75 - 0.25);
    const expectedDyaw = f32(f32(dyaw * genes.maxSpeed) * agentConfig.yaw2DYaw);

    let energyused = f32(0.25 * agentConfig.eat2Energy);
    energyused = f32(energyused + f32(0 * agentConfig.mate2Energy));
    energyused = f32(energyused + f32(0 * agentConfig.fight2Energy));
    energyused = f32(energyused + f32(0.5 * agent.speed2Energy()));
    energyused = f32(energyused + f32(Math.abs(dyaw) * agent.yaw2Energy()));
    energyused = f32(energyused + 0); // fCns->getEnergyUse()
    energyused = f32(energyused + agentConfig.fixedEnergyDrain);
    energyused = f32(energyused + f32(0 * agentConfig.light2Energy)); // hasLightBehavior
    let expectedDenergy = f32(energyused * genes.strength * f32(1.0 + f32(agentConfig.ageEnergyMultiplier * ageBefore)));
    expectedDenergy = f32(expectedDenergy + f32(0 * maxEnergy)); // no population penalty
    expectedDenergy = f32(expectedDenergy * 1.0 * 1.0); // scale factors
    expectedDenergy = f32(expectedDenergy * agentConfig.energyUseMultiplier);

    expect(bitsOf(energyUsed)).toBe(bitsOf(expectedDenergy));
    expect(bitsOf(agent.energy().get(0))).toBe(bitsOf(f32(before.get(0) - expectedDenergy)));
    expect(bitsOf(agent.foodEnergy().get(0))).toBe(bitsOf(f32(before.get(0) - expectedDenergy)));

    // motion: `dx = -dpos * sin( yaw * DEGTORAD )` with yaw 0 -> 0; dz -> -dpos
    expect(agent.x()).toBe(positionBefore[0]);
    expect(bitsOf(agent.z())).toBe(bitsOf(f32(positionBefore[2] - dpos)));
    // steering: yaw was 0, so it is now the expected dyaw
    expect(bitsOf(agent.yaw())).toBe(bitsOf(expectedDyaw));
    // the step ages the agent and records its speed
    expect(agent.age()).toBe(ageBefore + 1);
    expect(bitsOf(agent.velocityZ())).toBe(bitsOf(f32(agent.z() - positionBefore[2])));

    // events: exactly one AgentBodyUpdatedEvent, carrying (denergy, energyused)
    const bodyEvents = deps.testEvents!.events.filter((event) => event.type === 32);
    expect(bodyEvents.length).toBe(1);
    expect((bodyEvents[0] as { energyUsed: number }).energyUsed).toBe(energyUsed);
  });

  it('does not move or turn when nothing is driven (yaw 0, speed 0)', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    const nerves = deps.testNerves!;
    nerves.set('Eat', 0);
    nerves.set('Mate', 0);
    nerves.set('Fight', 0);
    nerves.set('Speed', 0);
    nerves.set('Yaw', 0.5); // squash encoding off: oppose -> dyaw = 0.5 - 0.5 = 0
    nerves.set('YawOppose', 0.5);
    nerves.set('Focus', 0);

    const x = agent.x();
    const z = agent.z();
    const yawBefore = agent.yaw();
    agent.updateBody(1.0, agentConfig.speed2DPosition, 0, null);
    expect(agent.x()).toBe(x);
    expect(agent.z()).toBe(z);
    expect(bitsOf(agent.yaw())).toBe(
      bitsOf(f32(yawBefore + f32(f32(0 * deps.testGenes!.maxSpeed) * agentConfig.yaw2DYaw))),
    );
  });

  it('wraps around the world when the world wraps and dies inside blocked edges', () => {
    const deps = makeDeps();
    globals.wraparound = true;
    globals.worldsize = 100;
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    const nerves = deps.testNerves!;
    nerves.set('Eat', 0);
    nerves.set('Mate', 0);
    nerves.set('Fight', 0);
    nerves.set('Speed', 1);
    nerves.set('Yaw', 0.5);
    nerves.set('YawOppose', 0.5);
    nerves.set('Focus', 0);

    agent.setZ(-0.01);
    agent.setYaw(0); // heading -z, i.e. toward -worldsize
    agent.saveLastPosition();
    agent.updateBody(1.0, agentConfig.speed2DPosition, 0, null);
    // z went below -worldsize and was wrapped back into [-worldsize, 0]
    expect(agent.z()).toBeGreaterThanOrEqual(-globals.worldsize);
    expect(agent.z()).toBeLessThan(0);
  });

  it('carries and drops objects, tracking the carry radius', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();

    const object = makeCarryable(GObject.FOODTYPE, 3, 6.5);
    agent.pickupObject(object);
    expect(agent.numCarries()).toBe(1);
    expect(agent.carryRadius()).toBe(Math.max(agent.radius(), object.radius()));
    expect(object.carriedBy()).toBe(agent);
    expect(bitsOf(agent.carryEnergy())).toBe(
      bitsOf(f32(f32(deps.foodStatics.carryFood2Energy() * object.radius()) / deps.foodStatics.maxFoodRadius())),
    );

    agent.dropMostRecent();
    expect(agent.numCarries()).toBe(0);
    expect(object.carriedBy()).toBeNull();
    expect(bitsOf(agent.carryRadius())).toBe(bitsOf(agent.radius()));
  });

  it('counts lives and notifies listeners on Die()', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    expect(AgentStatics.agentsLiving).toBe(1);
    expect(agent.number()).toBe(1);

    const died: unknown[] = [];
    agent.addListener({ died: (a) => died.push(a) });
    agent.die();
    expect(died).toEqual([agent]);
    expect(agent.alive()).toBe(false);
    expect(AgentStatics.agentsLiving).toBe(0);
  });

  it('stamps the lifespan record the way lifespans.txt is written', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    agent.stampBirth(0, 1); // BR_SIMINIT
    agent.lifeSpan().setDeath(218, DeathReason.FIGHT);
    expect(agent.lifeSpan().birthReasonName()).toBe('SIMINIT');
    expect(agent.lifeSpan().deathReasonName()).toBe('FIGHT');
    expect(agent.lifeSpan().birth.step).toBe(0);
    expect(agent.lifeSpan().death.step).toBe(218);
  });

  it('gives an agent its gene budget (max energy, starvation threshold, cost scaling)', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    const sizeRel = f32(deps.testGenes!.size - agentConfig.minAgentSize);
    const expectedMaxEnergy = f32(
      agentConfig.minMaxEnergy +
        f32(f32(sizeRel * f32(agentConfig.maxMaxEnergy - agentConfig.minMaxEnergy)) / f32(agentConfig.maxAgentSize - agentConfig.minAgentSize)),
    );
    expect(bitsOf(agent.maxEnergy().get(0))).toBe(bitsOf(expectedMaxEnergy));
    expect(bitsOf(agent.starvationFoodEnergy().get(0))).toBe(
      bitsOf(f32(agentConfig.starvationEnergyFraction * expectedMaxEnergy)),
    );
    expect(bitsOf(agent.speed2Energy())).toBe(
      bitsOf(
        f32(
          f32(f32(f32(agentConfig.speed2Energy * deps.testGenes!.maxSpeed) * f32(agentConfig.minSizePenalty + sizeRel)) * agentConfig.maxSizePenalty) /
            // Native `agent.cc:741`: `( minSizePenalty + maxAgentSize - minAgentSize )`,
            // left to right — NOT `minSizePenalty + ( maxAgentSize - minAgentSize )`.
            f32(f32(agentConfig.minSizePenalty + agentConfig.maxAgentSize) - agentConfig.minAgentSize),
        ),
      ),
    );
    expect(bitsOf(agent.normalizedEnergy())).toBe(bitsOf(f32(1.0)));
  });

  it('reads a seed’s energy budget and mate wait from the seeding path', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(25, true);
    expect(agent.isSeed()).toBe(true);
    // randomSeedMateWait is false in this world, so `fLastMate = -mateWait` exactly.
    expect(agent.lastMate()).toBe(-25);
    // randomSeedEnergy false -> maxSeedEnergy * maxEnergy
    expect(bitsOf(agent.energy().get(0))).toBe(
      bitsOf(f32(agentConfig.maxSeedEnergy * agent.maxEnergy().get(0))),
    );
  });
});

// ---------------------------------------------------------------------------
// round-1 review pins — the native constants and the per-operand float narrowing
// ---------------------------------------------------------------------------

describe('L8 — native constants and float narrowing (round-1 review fixes)', () => {
  const configVector = loadVector<ConfigVector>('config.minitest_voff.json');

  beforeEach(() => {
    resetGlobals();
    resetAgentConfig();
    resetAgentStatics();
    processWorldfile(documentFromJs(configVector.keys));
    globals.worldsize = 100;
    globals.numEnergyTypes = 1;
  });

  it('hands native’s list directions (NEXT 1 / PREV 2) to anotherObj', () => {
    // Native `utils/objectxsortedlist.h:4-5` is `#define NEXT 1` / `#define PREV 2`, and
    // `objectxsortedlist::anotherObj` (objectxsortedlist.cc:129-139) prints
    // "ERROR--Unknown direction" and `exit(1)`s for anything else. The pre-fix port declared
    // PREV as 0 and passed that to the seam, where the native walk aborts.
    expect(GObject.NEXT).toBe(1);
    expect(GObject.PREV).toBe(2);

    const deps = makeDeps();
    const directions: number[] = [];
    const marks: number[] = [];
    const list: SortedObjectListLike = {
      setMark: (type: number) => marks.push(type),
      toMark: (type: number) => marks.push(type),
      anotherObj: (direction: number) => {
        directions.push(direction);
        return null;
      },
    };
    // `AgentDeps.sortedObjects` is readonly in the frozen contract; the seam is swapped for
    // this pin only (the agent reads `this.deps.sortedObjects` at call time).
    (deps as unknown as { sortedObjects: SortedObjectListLike }).sortedObjects = list;
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.avoidCollisions(GObject.AGENTTYPE);
    expect(directions).toEqual([GObject.PREV, GObject.NEXT]);
    expect(marks).toEqual([GObject.AGENTTYPE, GObject.AGENTTYPE, GObject.AGENTTYPE]);
  });

  it('truncates a randomly seeded mate wait toward zero (native C cast, not nint)', () => {
    const deps = makeDeps();
    agentConfig.randomSeedMateWait = true;
    deps.rng.drand48 = () => 0.44;
    const agent = Agent.getFreeAgent(deps);
    agent.grow(40, true);
    // Native `agent.cc:680` is `fLastMate = (long)( randpw() * -mateWait );` — truncation of
    // the double product. `nint` (the `misc.h:36` macro used for the Metabolism index) rounds
    // negatives away from zero, so the pre-fix port stored -18 for this seed.
    expect(Math.trunc(0.44 * -40)).toBe(-17);
    expect(agent.lastMate()).toBe(-17);
  });

  it('computes fSpeed from narrowed squares, as agent.cc:1435 does', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    const carrier = Agent.getFreeAgent(deps);
    carrier.grow(0, false);

    // Chosen so the native per-operand form and the single-rounding form differ (they do for
    // ~23% of random float32 pairs). A carried agent is snapped to its carrier by `PickedUp`,
    // so the step's `dx`/`dz` are the carrier's displacement between pickup and the update —
    // here exactly `u` and `v`.
    const u = 0.6874257922172546;
    const v = 0.9004657864570618;
    carrier.setX(0);
    carrier.setZ(0);
    agent.setX(5);
    agent.setZ(5);
    carrier.pickupObject(agent);
    expect(agent.beingCarried()).toBe(true);
    expect(agent.x()).toBe(carrier.x()); // `gobject::PickedUp` snaps the carried object
    carrier.setX(u);
    carrier.setZ(v);

    agent.updateBody(1.0, agentConfig.speed2DPosition, 0, carrier);
    expect(bitsOf(agent.velocityX())).toBe(bitsOf(u));
    expect(bitsOf(agent.velocityZ())).toBe(bitsOf(v));

    const perOperand = f32(Math.sqrt(f32(f32(u * u) + f32(v * v))));
    const singleRounding = f32(Math.sqrt(u * u + v * v));
    expect(bitsOf(perOperand)).not.toBe(bitsOf(singleRounding));
    expect(bitsOf(agent.speed())).toBe(bitsOf(perOperand));
  });

  it('associates the size-penalty denominator left to right, as agent.cc:741 does', () => {
    const deps = makeDeps();
    // Values chosen (by search) so the two associations give different floats.
    agentConfig.minSizePenalty = 4.182470798492432;
    agentConfig.minAgentSize = 1.2145298719406128;
    agentConfig.maxAgentSize = 3.1678273677825928;
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);

    const sizeRel = f32(deps.testGenes!.size - agentConfig.minAgentSize);
    const nativeDenominator = f32(
      f32(agentConfig.minSizePenalty + agentConfig.maxAgentSize) - agentConfig.minAgentSize,
    );
    const reassociated = f32(
      agentConfig.minSizePenalty + f32(agentConfig.maxAgentSize - agentConfig.minAgentSize),
    );
    expect(bitsOf(nativeDenominator)).not.toBe(bitsOf(reassociated));

    const expected = f32(
      f32(
        f32(
          f32(agentConfig.speed2Energy * deps.testGenes!.maxSpeed) *
            f32(agentConfig.minSizePenalty + sizeRel),
        ) * agentConfig.maxSizePenalty,
      ) / nativeDenominator,
    );
    expect(bitsOf(agent.speed2Energy())).toBe(bitsOf(expected));
  });

  it('narrows the collision distance² terms, so the approaching test matches native', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();

    // Geometry found by search over float32 inputs: here the native per-operand form says
    // "approaching" and the pre-fix single-rounding (double) form says "not approaching", so
    // the fix changes a collision decision — not just the last bits. The x/z range tests
    // below are re-checked explicitly, so the test cannot pass by the object simply being
    // outside the window.
    const lx = -29.02815055847168;
    const lz = 3.796597719192505;
    const x = -27.680822372436523;
    const z = 4.139699935913086;
    const ox = -28.375471115112305;
    const oz = 1.2617377042770386;
    const objectRadiusValue = 2.1406784057617188;

    agent.setX(lx);
    agent.setZ(lz);
    agent.saveLastPosition();
    agent.setX(x);
    agent.setZ(z);

    const object = makeCarryable(GObject.AGENTTYPE, 2, objectRadiusValue);
    object.setx(ox);
    object.setz(oz);
    let served = false;
    const collisionList: SortedObjectListLike = {
      setMark: () => {},
      toMark: () => {},
      anotherObj: () => {
        if (served) return null;
        served = true;
        return { obj: object };
      },
    };
    (deps as unknown as { sortedObjects: SortedObjectListLike }).sortedObjects = collisionList;

    // The x/z range tests the port runs before the distance test — asserted here so the pin
    // is known to exercise the decision, not the early-out.
    const agtRadius = f32(agent.radius() * 0.9);
    const objRadius = f32(objectRadiusValue * 0.9);
    expect(f32(ox - objRadius) > f32(Math.max(x, lx) + agtRadius)).toBe(false);
    expect(f32(ox + objRadius) < f32(Math.min(x, lx) - agtRadius)).toBe(false);
    expect(f32(oz - objRadius) > f32(Math.max(z, lz) + agtRadius)).toBe(false);
    expect(f32(oz + objRadius) < f32(Math.min(z, lz) - agtRadius)).toBe(false);

    // The step the port takes toward the object (`Math.abs(dx) > Math.abs(dz)` branch, both
    // forms narrow these the same way).
    const dx = f32(x - lx);
    const dz = f32(z - lz);
    expect(Math.abs(dx) > Math.abs(dz)).toBe(true);
    const s = f32(dz / dx);
    const xs = f32(lx + f32(dx / globals.worldsize));
    const zs = f32(lz + f32(s * f32(xs - lx)));

    const narrowed = (a: number, b: number): number => f32(f32(a * a) + f32(b * b));
    const nativeDo = narrowed(f32(ox - lx), f32(oz - lz));
    const nativeDs = narrowed(f32(ox - xs), f32(oz - zs));
    const doubleDo = (ox - lx) ** 2 + (oz - lz) ** 2;
    const doubleDs = (ox - xs) ** 2 + (oz - zs) ** 2;
    expect(nativeDs < nativeDo).toBe(true);
    expect(doubleDs < doubleDo).toBe(false);

    agent.avoidCollisionDirectional(GObject.NEXT, GObject.AGENTTYPE);

    // the port took the native branch: repositioned onto the fixed coordinates + one event
    const expected = agent.getCollisionFixedCoordinates(lx, lz, x, z, ox, oz, agtRadius, objRadius);
    expect(bitsOf(agent.x())).toBe(bitsOf(expected.xf));
    expect(bitsOf(agent.z())).toBe(bitsOf(expected.zf));
    const collisions = deps.testEvents!.events.filter((event) => event.type === 256);
    expect(collisions.length).toBe(1);
    expect((collisions[0] as unknown as { ot: number }).ot).toBe(0); // OT_AGENT
  });
});

