const SWEEP_CONFIG = loadVector<ConfigVector>('config.minitest_voff.json');

describe('the contraction sweep — drives for the agent sites (t_981fcace)', () => {
  beforeEach(() => {
    resetGlobals();
    resetAgentConfig();
    resetAgentStatics();
    processWorldfile(documentFromJs(SWEEP_CONFIG.keys));
    globals.worldsize = 100;
    globals.numEnergyTypes = 1;
  });

  function steppedAgent(drive: BarrierDrive): Agent {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    const nerves = deps.testNerves!;
    nerves.set('Eat', 0);
    nerves.set('Mate', 0);
    nerves.set('Fight', 0);
    nerves.set('Speed', drive.dpos);
    nerves.set('Yaw', 0.5); // YE_OPPOSE with YawOppose 0.5 -> dyaw = 0
    nerves.set('YawOppose', 0.5);
    nerves.set('Focus', 0);
    agent.setCarryRadius(fromBits(drive.cr));
    agent.setX(fromBits(drive.startX));
    agent.setZ(fromBits(drive.startZ));
    agent.setYaw(drive.yaw);
    serveOnce(deps, makeBarrier(drive));
    agent.updateBody(1.0, agentConfig.speed2DPosition, 0, null);
    return agent;
  }

  it('UpdateBody drives the fused barrier bounds (0x26a04-0x26a94)', () => {
    for (const drive of BARRIER_BOUND_DRIVES) {
      const agent = steppedAgent(drive);
      expect(
        `${hex(bitsOf(agent.x()))} ${hex(bitsOf(agent.z()))}`,
        `${drive.name}: ${drive.site}`,
      ).toBe(`${hex(drive.expectX)} ${hex(drive.expectZ)}`);
    }
  });

  it('UpdateBody drives the three fused `p` values (0x26b08/0x26b30/0x26b34)', () => {
    for (const drive of BARRIER_P_DRIVES) {
      const agent = steppedAgent(drive);
      expect(
        `${hex(bitsOf(agent.x()))} ${hex(bitsOf(agent.z()))}`,
        `${drive.name}: ${drive.site}`,
      ).toBe(`${hex(drive.expectX)} ${hex(drive.expectZ)}`);
    }
  });

  it('agent::FieldOfView calls the fused double fmadd (0x261d0)', () => {
    // `focus * ( maxFocus - minFocus ) + minFocus`, the bounds' difference a float `fsub`
    // (`0x261c4`), the multiply-add one `fmadd d0, d0, d2, d1` in binary64 (`0x261d0`), the
    // `float` return an `fcvt` (`0x261d4`). Exact-rational: fused 0xbeff3b6f, the pre-sweep
    // form (product rounded to float first) 0xbeff3b6e.
    agentConfig.minFocus = fromBits(0xbf000000);
    agentConfig.maxFocus = fromBits(0x3f34fdf4);
    agentConfig.invertFocus = false;
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    deps.testNerves!.set('Focus', fromBits(0x3aa2db62));
    expect(hex(bitsOf(agent.fieldOfView()))).toBe(hex(0xbeff3b6f));
    // and the drive is not vacuous: the pre-sweep form is a different bit pattern here
    expect(
      hex(
        bitsOf(
          f32(
            f32(fromBits(0x3aa2db62) * f32(fromBits(0x3f34fdf4) - fromBits(0xbf000000))) +
              fromBits(0xbf000000),
          ),
        ),
      ),
    ).toBe(hex(0xbeff3b6e));
  });

  it('agent::UpdateVision drives the fused pitch (0x262f0) and yaw (0x26338)', () => {
    agentConfig.vision = true;
    agentConfig.enableVisionPitch = true;
    agentConfig.enableVisionYaw = true;
    agentConfig.minVisionPitch = fromBits(0xc3340000);
    agentConfig.maxVisionPitch = fromBits(0x43340000);
    agentConfig.minVisionYaw = fromBits(0xc3340000);
    agentConfig.maxVisionYaw = fromBits(0x43340000);
    const deps = makeDeps();
    const seen = { pitch: [] as number[], yaw: [] as number[] };
    (deps as unknown as { visionCamera: unknown }).visionCamera = {
      setFrustum: () => {},
      setAspect: () => {},
      setPitch: (pitch: number) => seen.pitch.push(pitch),
      setYaw: (yaw: number) => seen.yaw.push(yaw),
    };
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    const nerves = deps.testNerves!;
    // `nerve * ( maxVision* - minVision* ) + minVision*`, one binary64 `fmadd` then an `fcvt`
    const PITCH_CASES: readonly (readonly [number, number])[] = [
      [0x3b070111, 0xc3334227],
      [0x3b6410b6, 0xc332bf49],
      [0x3b6d6777, 0xc332b227],
    ];
    for (const [nerve, fused] of PITCH_CASES) {
      nerves.set('VisionPitch', fromBits(nerve));
      nerves.set('VisionYaw', fromBits(nerve));
      seen.pitch.length = 0;
      seen.yaw.length = 0;
      agent.updateVision();
      expect(hex(bitsOf(seen.pitch[0]!)), `pitch ${hex(nerve)}`).toBe(hex(fused));
      expect(hex(bitsOf(seen.yaw[0]!)), `yaw ${hex(nerve)}`).toBe(hex(fused));
      // non-vacuity: the pre-sweep form rounds the product to float first
      const delta = f32(fromBits(0x43340000) - fromBits(0xc3340000));
      expect(hex(bitsOf(f32(f32(fromBits(nerve) * delta) + fromBits(0xc3340000))))).toBe(
        hex(fused === 0xc3334227 ? 0xc3334226 : fused === 0xc332bf49 ? 0xc332bf48 : 0xc332b226),
      );
    }
  });
});

// ---------------------------------------------------------------------------
// 7. the contraction sweep — round 4: the L8 heuristic-fitness sites (t_981fcace)
// ---------------------------------------------------------------------------

/**
 * Review round 3 (contract lens) took this card's own `fused_map2.txt` and found three
 * single-precision fused multiply-adds in L8's own lane that no outcome list mentioned:
 *
 *   `__ZN5agent11lastrewardsEff`                `0x25e3c fmadd s0, s9, s0, s1`
 *   `__ZN5agent25ProjectedHeuristicFitnessEv`   `0x25ed4 fmadd s0, s10, s0, s9`
 *                                               `0x25f00 fmadd s0, s1, s2, s0`
 *
 * Neither is `setradius`-shaped: the age term of `lastrewards` keeps its own `fmul`
 * (`0x25e34`) + `fdiv` (`0x25e38`), and `ProjectedHeuristicFitness`'s `base` keeps its three
 * separate float operations (`0x25e98`/`0x25ea4 fmul`, `0x25eb0 fdiv`) — only the products
 * that are added are contracted. The pre-sweep port rounded each of those products, which
 * differs in the last bit on 2.4 % (`lastrewards`) and 12.0 % / 10.8 % (the two projected
 * sites, 17.6 % together) of 200 000 exact-rational samples.
 *
 * Both drives below call the ported code (`lastRewards`, `projectedHeuristicFitness`), so a
 * revert fails here directly. Every constant is the correctly-rounded binary32 of the exact
 * rational expression, derived in `dis/gen_heur_pins.py` under t_981fcace's workspace — never
 * from the port's helpers — and every case is checked non-vacuous against the pre-sweep form.
 *
 * The runtime scalars the derivation depends on are asserted too, so the pin cannot go stale
 * silently: `MaxAge()` = 750 (`0x443b8000`, `makeGenes().lifespan`), `fMaxEnergy.sum()` = 750
 * (`agent::initenergy` with the voff worldfile, `f32(500 + f32(0.75 * 500) / 1.5)`) and
 * `fAge` = 6 (`0x40c00000`; native's `long fAge`, `scvtf`-ed by the binary).
 */
describe('the contraction sweep — the lastrewards/ProjectedHeuristicFitness sites (t_981fcace)', () => {
  beforeEach(() => {
    resetGlobals();
    resetAgentConfig();
    resetAgentStatics();
    processWorldfile(documentFromJs(SWEEP_CONFIG.keys));
    globals.worldsize = 100;
    globals.numEnergyTypes = 1;
  });

  /** The four `Simulation` seams `ProjectedHeuristicFitness` reads, as mutable stubs. */
  interface SimSeams {
    lifeFractionSamples: () => number;
    lifeFractionRecent: () => number;
    energyFitnessParameter: () => number;
    ageFitnessParameter: () => number;
  }

  function sweepAgent(): { agent: Agent; sim: SimSeams } {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    // the derived scalars the exact-rational pins assume — asserted, so drift fails loudly
    expect(hex(bitsOf(agent.maxAge())), 'MaxAge()').toBe('0x443b8000'); // 750
    expect(hex(bitsOf(agent.maxEnergy().sum())), 'fMaxEnergy.sum()').toBe('0x443b8000');
    (agent as unknown as { fAge: number }).fAge = 6; // 0x40c00000
    return { agent, sim: deps.simulation as unknown as SimSeams };
  }

  it('agent::lastrewards contracts the energy product (0x25e3c)', () => {
    const { agent } = sweepAgent();
    expect(hex(bitsOf(agent.currentHeuristicFitness())), 'fHeuristicFitness starts at 0').toBe(
      '0x00000000',
    );
    // `fEnergy.sum() / fMaxEnergy.sum()` = 265.1640625 / 750
    agent.setEnergy(new Energy(fromBits(0x43849500)));
    expect(hex(bitsOf(agent.normalizedEnergy())), 'normalizedEnergy()').toBe('0x3eb504c7');
    agent.lastRewards(fromBits(0x4031842a), fromBits(0x3ecd863a));
    expect(hex(bitsOf(agent.currentHeuristicFitness())), 'lastrewards').toBe('0x3f7bddf8');
    // non-vacuity: the pre-sweep form rounds the energy product to float first (0x25e3c is
    // `fmadd s0, s9, s0, s1`, i.e. `f32(ef*ne + ageTerm)` in ONE rounding; the age term itself
    // is `f32(f32(af * 6) / 750)` from `0x25e34`/`0x25e38` and is the same in both forms)
    const ageTerm = f32(f32(fromBits(0x3ecd863a) * 6) / 750);
    expect(hex(bitsOf(ageTerm))).toBe('0x3b5274f8');
    expect(hex(bitsOf(f32(f32(fromBits(0x4031842a) * fromBits(0x3eb504c7)) + ageTerm)))).toBe(
      '0x3f7bddf9',
    );
  });

  it('agent::ProjectedHeuristicFitness contracts both products (0x25ed4/0x25f00)', () => {
    const { agent, sim } = sweepAgent();
    const hf = fromBits(0x42b79cac);
    const lfr = fromBits(0x3f01b6f7);
    const efp = fromBits(0x3e15f501);
    const afp = fromBits(0x3ea63ee3);
    sim.lifeFractionSamples = () => 60; // >= 50 takes the fused `return` arm
    sim.lifeFractionRecent = () => lfr;
    sim.energyFitnessParameter = () => efp;
    sim.ageFitnessParameter = () => afp;
    // no setter for `fHeuristicFitness`; poke the private field (setup only — the site under
    // test is `projectedHeuristicFitness`, and poking keeps this drive independent of
    // `lastRewards`, so a revert there cannot mask a revert here)
    (agent as unknown as { fHeuristicFitness: number }).fHeuristicFitness = hf;
    agent.setEnergy(new Energy(fromBits(0x44219bd9)));
    expect(hex(bitsOf(agent.normalizedEnergy())), 'normalizedEnergy()').toBe('0x3f5ca65d');
    expect(hex(bitsOf(agent.projectedHeuristicFitness())), 'projectedHeuristicFitness').toBe(
      '0x45b5b840',
    );
    // the `base` term is the same in both forms (three separate float ops, all right)
    const base = f32(f32(f32(hf * lfr) * 750) / 6);
    expect(hex(bitsOf(base))).toBe('0x45b5b5ec');
    // non-vacuity: the pre-sweep form rounds both products before the adds
    const ne = fromBits(0x3f5ca65d);
    expect(hex(bitsOf(f32(f32(base + f32(efp * ne)) + f32(afp * lfr))))).toBe('0x45b5b83f');
    // …and it is the *projection* the port returns, not the raw fitness
    expect(agent.projectedHeuristicFitness()).not.toBe(hf);
  });
});

// ---------------------------------------------------------------------------
// The contraction-sweep follow-up (t_2a625bd5) — `agent::LastEatDistance`
// ---------------------------------------------------------------------------

describe('the contraction sweep follow-up — agent::LastEatDistance (t_2a625bd5)', () => {
  beforeEach(() => {
    resetGlobals();
    resetAgentConfig();
    resetAgentStatics();
    processWorldfile(documentFromJs(SWEEP_CONFIG.keys));
    globals.worldsize = 100;
    globals.numEnergyTypes = 1;
  });

  /**
   * `agent::LastEatDistance` (`agent.h:419` — `dist( fPosition[0], fPosition[2],
   * fLastEatPosition[0], fLastEatPosition[2] )`, `dist` = `utils/misc.h:96`), inlined into
   * `TSimulation::GetMatePotential` at 0x9947c-0x9948c:
   *
   *   99480: fsub  s4, s4, s6      ; dz
   *   99484: fmul  s4, s4, s4      ; f32(dz*dz)   <- the one rounded square
   *   99488: fmadd s3, s3, s3, s4  ; dx*dx + that, ONE rounding
   *   9948c: fsqrt s3, s3          ; **float** sqrt
   *
   * The pre-change port used `Math.hypot` — a binary64 hypotenuse whose `f32` narrowing
   * differs from the fused float `sqrt` (this generator, `dis/gen_final.py`, found 3 such
   * pairs in its first 8 candidates). The `hypot` column below is `bitsOf(Math.hypot(dx,
   * dz))` measured in V8 for the same operands, so the non-vacuity assertion is the
   * *revert's* value, not a third form.
   */
  const LAS_CASES = [
    { x: 0x404d6fda, z: 0xc1a20e37, ex: 0x4189fb6a, ez: 0xc173ca1f, fused: 0x416e88f3, hypot: 0x416e88f4 },
    { x: 0x41a75e4c, z: 0xc0db7660, ex: 0x419bb6ad, ez: 0xc191857c, fused: 0x4136cdca, hypot: 0x4136cdc9 },
    { x: 0x4063e453, z: 0xc134939d, ex: 0x4170c2f2, ez: 0xc140ebe7, fused: 0x413833e2, hypot: 0x413833e1 },
    { x: 0x41b6e86c, z: 0xc1358636, ex: 0x40c7316f, ez: 0xc05dc510, fused: 0x4193487c, hypot: 0x4193487d },
  ];

  it('contracts the square sum and takes the float sqrt (0x99488/0x9948c)', () => {
    const deps = makeDeps();
    const agent = Agent.getFreeAgent(deps);
    agent.grow(0, false);
    agent.setGenomeReady();
    const poke = agent as unknown as {
      fPosition: [number, number, number];
      fLastEatPosition: [number, number, number];
    };

    for (const c of LAS_CASES) {
      const label = `${hex(c.x)}/${hex(c.z)}`;
      poke.fPosition[0] = fromBits(c.x);
      poke.fPosition[2] = fromBits(c.z);
      poke.fLastEatPosition[0] = fromBits(c.ex);
      poke.fLastEatPosition[2] = fromBits(c.ez);

      expect(hex(bitsOf(agent.lastEatDistance())), `lastEatDistance ${label}`).toBe(hex(c.fused));

      // non-vacuity: the pre-change `Math.hypot` form (narrowed the way the drive narrows
      // every compared value — the nerve/array store in the site's own callers is a double,
      // but this site *returns* a float and the two forms already differ as floats)
      const dx = f32(fromBits(c.x) - fromBits(c.ex));
      const dz = f32(fromBits(c.z) - fromBits(c.ez));
      expect(hex(bitsOf(Math.hypot(dx, dz))), `pre-change hypot ${label}`).toBe(hex(c.hypot));
      expect(hex(c.hypot), `non-vacuous ${label}`).not.toBe(hex(c.fused));
    }
  });
});

/**
 * Lane L8 — the motion pair in `UpdateBody` (`__sincos_stret`, task t_1263719e).
 *
 * The shipped `agent::UpdateBody` reaches Apple's **double** `__sincos_stret` for
 * `sin/cos( yaw() * DEGTORAD )` (`0x265f8 → bl 0xa3988`, and it is *not* the `sinf`/`cosf` pair —
 * PARITY's `W1d-fu/camera-calls-sincosf-not-sinf-cosf`), so the port calls lane W1d's transcribed
 * `libm.sin`/`libm.cos`. Two measured facts, and the second is why this test has to assert the
 * call site rather than a value:
 *
 *  * the functions disagree on ~4 % of the yaw domain (counts pinned below), and
 *  * narrowing `-dpos * …` to `f32` makes the disagreement **invisible in every recorded
 *    artifact** — 0 flips over the whole (yaw, dpos) grid below — so no golden, farm line or
 *    per-agent trace can catch a silent revert to V8's `Math.sin`/`Math.cos`.
 */
describe('L8 — UpdateBody motion through the oracle’s `__sincos_stret` (t_1263719e)', () => {
  /** `yaw()` is a `float` in [0, 360); 20,000 points, `360 / 20000 = 0.018` exactly. */
  const YAWS: readonly number[] = Array.from({ length: 20000 }, (_, i) => f32(i * 0.018));
  /**
   * `dpos` is native's `f32( speedNerve * MaxSpeed * MotionRate )`, clipped to `MaxVelocity`;
   * these four speeds bracket the band the recorded worlds reach.
   */
  const DPOS: readonly number[] = [0.05, 0.1, 0.25, 0.5].map((v) => f32(v));

  it('disagrees with V8 on 847 (sin) / 953 (cos) of 20,000 yaws, and the narrowing hides all of it', () => {
    const sLibm: number[] = [];
    const sV8: number[] = [];
    const cLibm: number[] = [];
    const cV8: number[] = [];
    let sinDiff = 0;
    let cosDiff = 0;

    for (const yaw of YAWS) {
      // `yaw()` is a float, `DEGTORAD` (0.017453292) is the native double literal, so the call's
      // argument is a double — exactly what `__sincos_stret` received.
      const arg = yaw * DEGTORAD;
      const sl = libmSin(arg);
      const sv = Math.sin(arg);
      const cl = libmCos(arg);
      const cv = Math.cos(arg);
      sLibm.push(sl);
      sV8.push(sv);
      cLibm.push(cl);
      cV8.push(cv);
      if (sl !== sv) sinDiff++;
      if (cl !== cv) cosDiff++;
    }

    let sinFlip = 0;
    let cosFlip = 0;
    let samples = 0;
    for (const dpos of DPOS) {
      for (let i = 0; i < YAWS.length; i++) {
        samples++;
        if (f32(-dpos * sLibm[i]!) !== f32(-dpos * sV8[i]!)) sinFlip++;
        if (f32(-dpos * cLibm[i]!) !== f32(-dpos * cV8[i]!)) cosFlip++;
      }
    }

    expect([sinDiff, cosDiff], 'raw disagreement counts on the yaw domain').toEqual([847, 953]);
    expect([sinFlip, cosFlip], 'flips after the f32 narrowing').toEqual([0, 0]);
    expect(samples, 'the (yaw, dpos) grid').toBe(80000);
  });

  it('the motion site calls the transcribed pair, not V8', () => {
    const source = readFileSync(join(HERE, '..', 'src', 'model', 'agent', 'agent.ts'), 'utf8');

    expect(source).toContain('dx = f32(-dpos * libmSin(this.yaw() * DEGTORAD));');
    expect(source).toContain('dz = f32(-dpos * libmCos(this.yaw() * DEGTORAD));');
    // the pre-change form, so the shortcut cannot come back unnoticed (no golden can see it)
    expect(source).not.toContain('f32(-dpos * Math.sin(');
    expect(source).not.toContain('f32(-dpos * Math.cos(');
  });
});

